namespace sv_37b8c607ced94dca9abe424f708cc0eb.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    string Description,
    DateTimeOffset Timestamp);

using sv_37b8c607ced94dca9abe424f708cc0eb.Client.Models;

namespace sv_37b8c607ced94dca9abe424f708cc0eb.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_37b8c607ced94dca9abe424f708cc0eb.Client.Models;
using sv_37b8c607ced94dca9abe424f708cc0eb.Client.Services;

namespace sv_37b8c607ced94dca9abe424f708cc0eb.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Seeds = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            "TRK-001",
            "In Transit",
            "Memphis, TN",
            new DateTimeOffset(2026, 6, 25, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", new DateTimeOffset(2026, 6, 20, 9, 0, 0, TimeSpan.Zero)),
                new("Arrived at sorting facility", new DateTimeOffset(2026, 6, 21, 3, 30, 0, TimeSpan.Zero)),
                new("In transit to destination", new DateTimeOffset(2026, 6, 22, 14, 15, 0, TimeSpan.Zero)),
            }),

        ["TRK-002"] = new Shipment(
            "TRK-002",
            "Delivered",
            "Austin, TX",
            new DateTimeOffset(2026, 6, 21, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", new DateTimeOffset(2026, 6, 18, 10, 0, 0, TimeSpan.Zero)),
                new("In transit", new DateTimeOffset(2026, 6, 19, 8, 0, 0, TimeSpan.Zero)),
                new("Out for delivery", new DateTimeOffset(2026, 6, 21, 7, 0, 0, TimeSpan.Zero)),
                new("Delivered", new DateTimeOffset(2026, 6, 21, 11, 42, 0, TimeSpan.Zero)),
            }),

        ["TRK-003"] = new Shipment(
            "TRK-003",
            "Processing",
            "Seattle, WA",
            new DateTimeOffset(2026, 6, 28, 18, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Label created", new DateTimeOffset(2026, 6, 22, 16, 0, 0, TimeSpan.Zero)),
                new("Awaiting carrier pickup", new DateTimeOffset(2026, 6, 23, 0, 30, 0, TimeSpan.Zero)),
            }),
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (Seeds.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_37b8c607ced94dca9abe424f708cc0eb.Client.Models
@using sv_37b8c607ced94dca9abe424f708cc0eb.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracking> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>…</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <h2>Shipment @_shipment.TrackingNumber</h2>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h3>Status Updates</h3>
    <ul>
        @foreach (var update in _shipment.StatusUpdates)
        {
            <li>
                <strong>@update.Timestamp.ToString("g")</strong> &mdash; @update.Description
            </li>
        }
    </ul>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _shipment = null;
        _errorMessage = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed — silently stop.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

